function Field({ label }: { label: string }) {
  const inputRef = useRef<HTMLInputElement>(null)
  const count = useRef(0) // box — UI will NOT update
  const [n, setN] = useState(0) // state — UI will update

  function focus() {
    inputRef.current?.focus() // handler: OK
    count.current += 1
  }
  // if (inputRef.current) ... during render is a concurrent footgun
  return <input ref={inputRef} aria-label={label} onFocus={focus} value={n} />
}

